# Tenant-owned tables with a plain `organisation_id = current tenant` policy.
TENANT_TABLES = ("branches", "roles", "role_permissions", "membership_roles")
ALL_RLS_TABLES = (*TENANT_TABLES, "organisations", "organisation_memberships", "audit_logs")


def _security_upgrade() -> None:
    # Scope helpers. Settings are transaction-local and set by the application
    # (app.core.db) at the start of every transaction. Unset => NULL => no rows.
    op.execute("""
        CREATE FUNCTION app_current_org() RETURNS uuid LANGUAGE sql STABLE AS
        $$ SELECT NULLIF(current_setting('app.organisation_id', true), '')::uuid $$;
        CREATE FUNCTION app_current_user() RETURNS uuid LANGUAGE sql STABLE AS
        $$ SELECT NULLIF(current_setting('app.user_id', true), '')::uuid $$;
        CREATE FUNCTION app_platform_scope() RETURNS boolean LANGUAGE sql STABLE AS
        $$ SELECT coalesce(current_setting('app.platform_scope', true), '') = 'on' $$;
    """)

    for table in ALL_RLS_TABLES:
        # FORCE applies policies to the table owner too; only superusers bypass.
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")

    for table in TENANT_TABLES:
        op.execute(f"""
            CREATE POLICY tenant_isolation ON {table}
            USING (organisation_id = app_current_org())
            WITH CHECK (organisation_id = app_current_org())
        """)

    # Memberships: full access inside the current tenant; a user may also read
    # their own memberships so they can choose which organisation to work in.
    op.execute("""
        CREATE POLICY tenant_isolation ON organisation_memberships
        USING (organisation_id = app_current_org())
        WITH CHECK (organisation_id = app_current_org());
        CREATE POLICY own_memberships_read ON organisation_memberships FOR SELECT
        USING (user_id = app_current_user());
    """)

    # Organisations: the current tenant; organisations the user belongs to
    # (read-only); and platform scope for tenant administration (status,
    # subscription). Platform scope is NOT granted on any other table.
    op.execute("""
        CREATE POLICY tenant_isolation ON organisations
        USING (id = app_current_org())
        WITH CHECK (id = app_current_org());
        CREATE POLICY member_read ON organisations FOR SELECT
        USING (id IN (SELECT organisation_id FROM organisation_memberships
                      WHERE user_id = app_current_user()));
        CREATE POLICY platform_admin ON organisations
        USING (app_platform_scope())
        WITH CHECK (app_platform_scope());
    """)

    # Audit log: append-only. Read within the tenant; insert for the tenant,
    # platform-level events (no organisation) or platform-scope actions.
    op.execute("""
        CREATE POLICY tenant_read ON audit_logs FOR SELECT
        USING (organisation_id = app_current_org());
        CREATE POLICY append ON audit_logs FOR INSERT
        WITH CHECK (organisation_id IS NULL
                    OR organisation_id = app_current_org()
                    OR app_platform_scope());

        CREATE FUNCTION audit_logs_block_mutation() RETURNS trigger LANGUAGE plpgsql AS
        $$ BEGIN RAISE EXCEPTION 'audit_logs is append-only'; END $$;
        -- Statement-level, so any attempt fails loudly even when RLS hides every row.
        CREATE TRIGGER audit_logs_append_only BEFORE UPDATE OR DELETE OR TRUNCATE ON audit_logs
            FOR EACH STATEMENT EXECUTE FUNCTION audit_logs_block_mutation();
    """)

    # Grants for the application role (created by infrastructure, not here).
    role = get_settings().app_db_role
    op.execute(f"""
        DO $$
        BEGIN
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{role}') THEN
                GRANT USAGE ON SCHEMA public TO {role};
                GRANT SELECT, INSERT, UPDATE, DELETE ON
                    organisations, branches, users, roles, role_permissions,
                    organisation_memberships, membership_roles TO {role};
                GRANT SELECT ON permissions TO {role};
                GRANT SELECT, INSERT ON audit_logs TO {role};
            END IF;
        END $$;
    """)


